\label{T1}
Let $I_1, I_2 \subset \mathbb{R}^2$ be two  non-overlapping (but possibly intersecting)  line segments with $|I_1|+|I_2|=2$. Let $\nu$ be arc-length measure on both $I_1$ and $I_2$ normalized (divided by 2) so as to be a probability measure. We record the following three facts. 
\begin{itemize}
\item[(I)]  {\bf Colinear line segments.} If $I_1$ and $I_2$ are collinear line segments, then, by results of Dutkay and Lai \cite{DL2014} and {\L}aba \cite{laba2001}, the  measure $\nu$ is spectral (i.e.\ the set $I_1 \cup I_2$ is a spectral set in ${\mathbb R}$) if and only if the gap between $I_1$ and $I_2$ is an integer when $|I_1| = |I_2|$, and the gap between $I_1$ and $I_2$ is an even integer when $|I_1| \neq |I_2|$. (Refer to Fig. \ref{twolineco}) 
\item[(II)]   {\bf Parallel line segments.}  If $I_1$ and $I_2$ are parallel line segments (non-collinear)   of equal length, Kolountzakis and Lai \cite[ \S 6]{kolountzakis2025non} show that whenever  the measure $\nu$ is spectral  it always has a line spectrum but also admits a spectrum that is not contained in any line. (Refer to Fig. \ref{twolineco})
\begin{figure}[htbp]
  \centering
\includegraphics[width=1.0\textwidth]{twolineco.jpg}                                 
  \caption{(I)  and  (II).} \label{twolineco}
\end{figure}
\item[(III)] {\bf Non-parallel line segments.} If $I_1$ and $I_2$ are two non-parallel line segments, then there exists an invertible affine map $T(x)=A x+ b$ with $A \in GL(2, \mathbb{R})$ such that $T\left(I_1\right)$ is contained in the $x$-axis and $T\left(I_2\right)$ is contained in the $y$-axis. Moreover, if $\mu$ is a spectral measure with spectrum $\Lambda \subset \mathbb{R}^2$, then the push-forward measure $\nu=T_{\#} \mu$ is again spectral, with spectrum $(A^{-1})^T \Lambda$. In particular, if $\Lambda$ is contained in a line $L\subset\mathbb{R}^2$, then $(A^{-1})^T\Lambda$ is contained in the line $(A^{-1})^T L$. Thus the property of being spectral is invariant under invertible affine changes of variables, and we may work in this normalized configuration without loss of generality. Notice that, additionally, we can always choose this affine transformation so that $T(I_1)$ and $T(I_2)$ have the same lengths as $I_1$ and $I_2$ (Refer to Fig. \ref{twolineself}). 
In other words, when we study the spectrality of the arc-length measure   supported on two non-parallel line segments in the plane, we may reduce the problem to the study of the spectrality of the   measure
\begin{equation}\label{rho-measure}
\rho=\frac{1}{2}L_{[t_1, t_1+T_1]}\times\delta_0+\frac{1}{2}\delta_0\times L_{[t_2, t_2+T_2]}   \text{ with } T_1+T_2=2.
\end{equation}
\end{itemize}

\label{twoline1}
Let $t_1,t_2\in\mathbb{R}$ and  $T_1,T_2>0$ with $T_1+T_2=2$. Consider the measure
\[
\rho=\frac{1}{2}L_{[t_1, t_1+T_1]}\times\delta_0+\frac{1}{2}\delta_0\times L_{[t_2, t_2+T_2]}.
\]
Then $\rho$ is a spectral measure if and only if one of the following  statements hold.
\begin{itemize}
\item[(I)] When $T_1=T_2$, we have  $t_1+t_2 \in\mathbb{Z} \setminus\{-1\}$ or $t_1-t_2 \in \mathbb{Z} \setminus\{0\}$.
\item[(II)] When $T_1\neq T_2$, we have $t_1+t_2\in 2\mathbb{Z}$ or $t_1-t_2-T_2\in 2\mathbb{Z}$ (equivalently, $t_2-t_1-T_1\in 2\mathbb{Z}$).
\end{itemize}
Moreover, if $\rho$ is a spectral measure, then every spectrum of $\rho$ that contains the origin is contained in either the line $y=x$ or the line $y=-x$. More precisely, if $0\in\Lambda$ is a spectrum of $\rho$, then $\Lambda$ has one of the following forms:
\begin{itemize}
\item[(I)] If $T_1=T_2$, then there exist $\alpha_1, \alpha_2\in(-\tfrac{1}{2}, \tfrac{1}{2}]$ such that
\begin{equation}\label{line-1}
 \Lambda=\begin{cases}
\{(n, -n),(n+\alpha_1, -(n+\alpha_1)): n\in \mathbb{Z}\}, & \text{if } t_1+t_2\in  \mathbb{Z}\setminus\{-1\},\\[6pt]
\{(n,  n),(n+\alpha_2,  n+\alpha_2): n\in \mathbb{Z}\}, & \text{if } t_1-t_2 \in  \mathbb{Z}\setminus\{0\}.
\end{cases}
\end{equation}
\item[(II)] If $T_1\neq T_2$, then
\begin{equation}\label{line-2}
 \Lambda=\begin{cases}
\{(\tfrac{n}{2}, -\tfrac{n}{2}): n\in \mathbb{Z}\}, & \text{if } t_1+t_2\in 2\mathbb{Z},\\[6pt]
\{(\tfrac{n}{2},  \tfrac{n}{2}): n\in \mathbb{Z}\}, & \text{if } t_1-t_2-T_2\in 2\mathbb{Z}.
\end{cases}
\end{equation}
\end{itemize}

\label{curve1}
 Let $\Gamma$ be a finite union of curves in $\mathbb{R}^d$, each of which is rectifiable and has finite, nonzero length, and let $\rho$ be the arc-length measure on $\Gamma$.   If   $\Lambda \subset \mathbb{R}^d$ is an orthogonal set for $\rho $,
then $\sup _{x \in \mathbb{R}^d}\#(\Lambda\cap B_R(x))= O(R)$ as $R\rightarrow\infty.$

\label{line segment}
Let $d \geq 2$ be an integer.
Let $L_1,\dots,L_m \subset \mathbb{R}^d$ be $m$  line segments, and let $\rho $ be the arc-length  measure on $\bigcup_{k=1}^{m} L_k$. If $\Lambda \subset \mathbb{R}^d$ is an orthogonal set for $\rho$, then $\sup _{x \in \mathbb{R}^d}\#(\Lambda\cap B_R(x))= O(R)$ as $R\rightarrow\infty.$

\label{propline}
Let $I_{1}=[a_1, a_1+T_1]\times\{h_1\}$ 
and  $I_{2}=[a_2, a_2+T_2]\times\{h_2\}$ with $h_1\neq h_2$, $T_1, T_2>0$ and $T_1+T_2=2$. 
For any $k>0$,  there exists a line $L$ (not perpendicular to $I_{1}$ and $I_{2}$) passing through the origin
such that
\begin{itemize}
\item [(a)] the orthogonal projection onto $L$ is injective  on $I_1\cup I_2$, and
\item [(b)] the length of the gap between the orthogonal projections of  $I_1$ and $I_2$  onto the line 
 $L$ is $k$ times the sum of the lengths of their projections.
\end{itemize}

\label{rem:projection-to-single-interval}
It is worth pointing out that if we only care to show the existence of some spectrum for two parallel line segments not on the same line then we can project them onto a straight line such the projection is injective (with the exception of the endpoints) and the support of the projection is a single interval, which always has a spectrum. To find this straight line suppose without loss of generality that our segments are parallel to the $x$-axis and define the straight line $S$ which joints the left endpoint of one interval with the right endpoint of the other. Project then onto $S^\perp$ to obtain a projection that is just one interval. (Refer to Fig.\ \ref{twopro}.)
\begin{figure}[htbp]
  \centering
\includegraphics[width=0.5\textwidth]{twopro.jpg}                                 
  \caption{Projecting to an interval.} \label{twopro}
\end{figure}

\label{lemtwo-l--1}
Let $0\in\Lambda$ be a spectrum for $L^2(\rho)$. Then the following two statements hold.
\begin{itemize}
\item[(I)]
  If $T_1\geq T_2$, then  $\Lambda$  has at most one point on each vertical line.
  \item[(II)]  If $T_1\leq T_2$, then  $\Lambda$  has at most one point on each horizontal line.
  \end{itemize}

\label{lemtwo-l--2}
Let $0\in\Lambda$ be a spectrum for $L^2(\rho)$. Then $\Lambda \not\subseteq \frac{\mathbb{Z}}{T_1}\times\frac{\mathbb{Z}}{T_2}$ and  
 $$\Lambda\subseteq \left\{(\lambda_1, \lambda_2 ): T( \lambda_1, \lambda_2 ) =\lambda_1\left(2 t_1+T_1\right)-\lambda_2\left(2 t_2+T_2\right)\in \mathbb{Z}\right\}.$$

\label{twoline1-2} If $\Lambda$ is a spectrum of $\rho$,  then  
\begin{align}\label{lem1-2-1}
\frac{2}{T_1}=\sum_{\lambda \in T_1\Lambda_x}\left|\hat{ \mathbf{1}}_{\left[0, 1\right]}\right|^2\left(s-\lambda\right)
\ \ \  \ \text{and} \ \ \ \ \frac{2}{T_2}=\sum_{\lambda \in T_2\Lambda_y}\left|\hat{ \mathbf{1}}_{\left[0, 1\right]}\right|^2\left(s-\lambda\right) 
\end{align} 
for   $s \in \mathbb{R}$.
Additionally,
\begin{enumerate}
\item [(I)] If  $\Lambda$  has at most one point on each vertical line, then $\Lambda_x$ is a periodic set.
\item [(II)] If  $\Lambda$  has at most one point on each horizontal line, then $\Lambda_y$ is a periodic set.
\end{enumerate}

\label{rem:tiling}
The tiling conditions \eqref{lem1-2-1} can also be expressed as follows:
 \begin{align}\label{lem1-2-1-1}
  2 T_1 =\sum_{\lambda \in \Lambda_x}\left|\hat{ \mathbf{1}}_{\left[0, T_1\right]}\right|^2\left(s-\lambda\right)
\ \ \  \ \text{and} \ \ \ \  2 T_2 =\sum_{\lambda \in \Lambda_y}\left|\hat{ \mathbf{1}}_{\left[0, T_2\right]}\right|^2\left(s-\lambda\right).
\end{align}

\label{lemtw}
Let $0\in\Lambda$  be a spectrum for $L^2(\rho)$,
then the following three  statements hold. 
\begin{itemize}
\item[(I)]
  If $T_1=T_2$, then for any $(\lambda_1, \lambda_2)\in(\Lambda-\Lambda)\setminus\{0\}$ with $|\lambda_1|\leq\frac{1}{2}$, we have $|\lambda_2|=|\lambda_1|$. 
\item[(II)] If $T_1\geq T_2$, then for any $(\lambda_1, \lambda_2)\in(\Lambda-\Lambda)\setminus\{0\}$ with $ |\lambda_1|=\frac{1}{2}$, we have $|\lambda_2|=|\lambda_1|=\frac{1}{2}$. 
\item[(III)] If $T_1\leq T_2$, then for any $(\lambda_1, \lambda_2)\in(\Lambda-\Lambda)\setminus\{0\}$ with $ |\lambda_2|=\frac{1}{2}$, we have $|\lambda_1|=|\lambda_2|=\frac{1}{2}$.
\end{itemize}

\label{lemtwo-l--1-2} 
Let $0\in\Lambda$  be  a spectrum for $L^2(\rho)$. Then \begin{enumerate}
\item [(I)] $\Lambda$  has multiplicity one;
\item [(II)] $\Lambda_x$ and $\Lambda_y$ are  periodic sets.
\end{enumerate}

\label{lemtw--t1}
Let $0\in\Lambda$  be a spectrum for $L^2(\rho)$,
then the following two statements hold. 
\begin{itemize}
\item[(I)]
 If $T_1 \neq T_2$, then $ \Lambda= \{(\frac{n}{2}, \frac{n}{2} ): n\in \mathbb{Z}\}$ or $ \Lambda= \{(\frac{n}{2}, -\frac{n}{2} ) : n\in \mathbb{Z}\}$.  
\item[(II)]
 If $T_1=T_2$, then  
$ \Lambda= \{(n, n ), (n+\alpha,n+\alpha): n\in \mathbb{Z}\}$ or $ \Lambda= \{(n, -n ), (n+\alpha, -(n+\alpha)): n\in \mathbb{Z}\}$ for some $\alpha\in(-\frac{1}{2}, \frac{1}{2}] \setminus\{0\}$.  
\end{itemize}

\label{lemtwo}
Suppose that $\rho $ is a spectral measure with the spectrum $0\in\Lambda$, then the following two statements hold.
\begin{itemize}
\item[(I)] 
If $(\frac{1}{2}, -\frac{1}{2})\in\Lambda$, then $t_1+t_2\in 2\mathbb{Z}$.
\item[(II)]
 If $(\frac{1}{2}, \frac{1}{2})\in\Lambda$, then $t_1-t_2-T_2\in 2\mathbb{Z}$.
 \end{itemize}

\label{lemtwo1-5}
Suppose that $\rho $ is a spectral measure with the spectrum $0\in\Lambda$ and $T_1=T_2$. Then the following two statements hold.
\begin{itemize}
\item[(I)] If $(1, -1)\in\Lambda$, then $t_1+t_2\in \mathbb{Z}$. 
\item[(II)]  If $(1, 1)\in\Lambda$, then $t_1-t_2 \in  \mathbb{Z}$.
\end{itemize}

\label{lemtwo1-5-1}
Suppose that  $T_1=T_2$ and one of the following three statements hold. \begin{itemize}
\item[(I)]  $t_1=t_2=-\frac{1}{2}$; 
\item[(II)]  $t_1-t_2=0$ and $t_1+t_2\notin {\mathbb Z}$; 
\item[(III)] 
  $t_1+t_2=-1$ and $t_1-t_2\notin {\mathbb Z}$.
\end{itemize}
Then  $\rho $ is not a spectral measure.

In fact, in (I), (II) and (III), the measure $\rho $ is symmetric. See Figure \ref{123pictures}. The conclusion can be directly derived from \cite[Theorem 1]{kolountzakis2025non} and   \cite{kolountzakis2025spectrality}.
\begin{figure}[htbp]
  \centering
\includegraphics[width=1\textwidth]{123picture.jpg}                                 
  \caption{(I), (II) and (III)  are symmetric measures.} \label{123pictures}
\end{figure}

\label{lemtw--t1-2}
Let $0\in\Lambda$  be a spectrum for $L^2(\rho)$.
Then the following two statements hold. 
\begin{itemize}
\item[(I)] 
  If $T_1=T_2$, then $ t_1+t_2 \in\mathbb{Z} \backslash\{-1\}$ or $  t_1-t_2 \in \mathbb{Z} \backslash\{0\}.$      
\item[(II)]  If $T_1\neq T_2$, then $t_1+t_2\in 2\mathbb{Z}$ or $t_1-t_2-T_2\in 2\mathbb{Z}$. \end{itemize}

This shows that the spectra of $\rho$  can only be contained in either the line  $y=x$ or $y=-x$.  Indeed, it is clear that the only orthogonal projections of $\rho$ onto a straight line that produce a measure which is a constant multiple of (one-dimensional) Lebesgue measure on its support (as is necessary for spectrality \cite{DL2014}) are the projections onto the straight lines $y=\pm x$. See Figure \ref{twolines}. The content of this section of the paper is therefore to rule out all other possible non-line spectra. 
\begin{figure}[htbp]
  \centering
\includegraphics[width=0.8\textwidth]{twolines.jpg}                                 
  \caption{ There are only two projection methods: $y=x$ or $y=-x$.} \label{twolines}
\end{figure}

\label{th:parallel}
Suppose $I$ is the line segment from $(0, 0)$ to $(100, 0)$.
Suppose $\mu$ is arc-length on the line segment $S_1 = I$, on $S_2 = I+(0, 1)$ and also on the the line segment $S_3 = I+(\alpha, 2)$, where $\alpha \in (0, \frac{1}{100})$ is an irrational number. Then $\mu$ is spectral but it does not have a line spectrum.

\label{th:L}
Suppose $\mu$ is arc-length on the four intervals
\begin{align*}
(0, 0) &- (1, 0),\\
(0, 0) &- (0, 1),\\
(1, 1) &- (1, 2),\\
(1, 1) &- (2, 1).
\end{align*}
Then $\mu$ is spectral but it does not have a line spectrum.

\label{lem:change measure}
Let  $\mu\in \mathcal{P} ({\mathbb R}^d) $ and $\Lambda\subset{\mathbb R}^d$ be an orthogonal set for $\mu$, i.e.
    \begin{equation}\label{eq:change measure 1}
	  \sum_{\lambda\in \Lambda} \left|\left\langle t, \lambda \right\rangle_{\mu}  \right|^2\le  \mu(D).
	\end{equation}
    Let $n>0$. Then for any $D\in \mathcal{D}_n$ with $\mu(D)>0$, and for any $t\in {\mathbb R}^d$, we have
	\begin{equation*}

    \sum_{\lambda\in \Lambda} \left|\left\langle \frac{1}{2^n}t, \frac{1}{2^n}\lambda \right\rangle_{\mu_{D}^{\Box}}  \right|^2\le \frac{1}{\mu(D)}.
	\end{equation*}

\label{thm:estimation}
   For any   measure $\mu  \in \mathcal{P}(\mathbb{R}^d)$  and   any orthogonal set $\Lambda$ for $\mu$, there exist constants $C$ and $\varrho$  such that  $t\in \mathbb{R}^d$ and $h>0$, we have
    \begin{equation}
	\# (\Lambda\cap B(t, h))
	 \le  C 2^{\sum_{D\in \mathcal{D}_n} -\mu(D)\log \mu(D)},
	 \end{equation}
     where $2^{n-1+\varrho}<h\le 2^{n+\varrho}$.

Notice that
	 \begin{equation}\label{eq:main thm 1}
	 2^{\sum_{D\in \mathcal{D}_n} -\mu(D)\log \mu(D)}=\prod_{D\in \mathcal{D}_n, \mu(D)>0} \mu(D)^{-\mu(D)}.
	 \end{equation}
	 Let $h>0$. Then there exists a positive integer $n_h$ such that $2^{n_h-1}< h\le 2^{n_h}$. Let $\epsilon>0$ and let $\delta=\delta(\epsilon, \mu)$, which is defined in Lemma \ref{lem:fourier transform}. Let $\varrho$ be the minimal integer such that $2^{-\varrho}<\delta$. For any $t\in \mathbb{R}^d$ and any $D\in \mathcal{D}_{n_h+\varrho}$, noticing that 
     $$
     \left|\frac{1}{2^{n_h+\varrho}}t-\frac{1}{2^{n_h+\varrho}}\lambda\right|<\delta, \text{ for any } \lambda\in \Lambda\cap B(t, h),
     $$
     by Lemma \ref{lem:fourier transform}, we have

\begin{equation}\label{eq:main thm 2}
	 \begin{split}
	 \epsilon^2 \cdot \#(\Lambda\cap B(t, h))
	 &\le \sum_{\lambda\in \Lambda\cap B(t, h)} \left|\left\langle \frac{1}{2^{n_h+\varrho}}t, \frac{1}{2^{n_h+\varrho}}\lambda \right\rangle_{\mu_{D}^{\Box}}  \right|^2\\
	 &\le \sum_{\lambda\in \Lambda} \left|\left\langle \frac{1}{2^{n_h+\varrho}}t, \frac{1}{2^{n_h+\varrho}}\lambda \right\rangle_{\mu_{D}^{\Box}}  \right|^2\\
 &\le \frac{1}{\mu({D})}.
	 \end{split}
	 \end{equation}
     The last inequality is due to   Lemma \ref{lem:change measure}. Since $\sum_{D\in \mathcal{D}_{n_h+\varrho}}\mu(D)=1$ and \eqref{eq:main thm 2} holds for all $D\in \mathcal{D}_{n_h+\varrho}$ with $\mu(D)>0$, we have
	 \begin{equation}\label{eq:main thm 3}
	 \begin{split}
\# (\Lambda\cap B(t, h))
	 &=\prod_{D\in \mathcal{D}_{n_h+\varrho}, \mu(D)>0}(\# (\Lambda\cap B(t, h)))^{\mu(D)} \\
	 &\le  \epsilon^{-2} \prod_{D\in \mathcal{D}_{n_h+\varrho}, \mu(D)>0} \mu(D)^{-\mu(D)}\\
  &=\epsilon^{-2} 2^{\sum_{D\in \mathcal{D}_{n_h+\varrho}} -\mu(D)\log \mu(D)}.
	 \end{split}
	 \end{equation}
	 The proof is complete.
